import{t,subscribeLanguage,translateUi}from './i18n.js';
import{uiLeaf}from './ui.js';
import{escapeStaff as esc}from './staff-markup.js';
export function mountStaffMessageActions(root,{getMessage,getRoom=()=>null,canReply=()=>true,onMissingSource=null,onTheme=null,onReply,onDelete,onClear=()=>{},onNotice=()=>{},isActive=()=>true,actorId}={}){
 const doc=root.ownerDocument,win=doc.defaultView,dialog=doc.createElement('dialog');dialog.className='staff-message-menu';dialog.setAttribute('aria-label',t('messageDeletionUi.actions'));root.append(dialog);
 let disposed=false,selected=null,mode='message',trigger=null,press=null,timer=null,highlight=null,highlightTimer=null;
 const live=()=>!disposed&&isActive();
 function clearHighlight(){if(highlightTimer!==null)win.clearTimeout(highlightTimer);highlightTimer=null;if(highlight){highlight.element.classList.remove('is-reply-source');if(highlight.tabIndex===null)highlight.element.removeAttribute('tabindex');else highlight.element.setAttribute('tabindex',highlight.tabIndex);}highlight=null;}
 function jumpToSource(id){if(!live())return;const message=getMessage(id);if(!message){if(onMissingSource)onMissingSource(id);else onNotice('messageDeletionUi.sourceNotLoaded',true);return;}if(message.redacted){onNotice('messageDeletionUi.unavailable',true);return;}const target=[...root.querySelectorAll('[data-message]')].find(element=>element.dataset.message===id);if(!target){onNotice('messageDeletionUi.sourceNotLoaded',true);return;}close();highlight={element:target,tabIndex:target.getAttribute('tabindex')};target.tabIndex=-1;target.classList.add('is-reply-source');const reduced=win.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches===true||doc.body.classList.contains('reduce-motion');target.scrollIntoView?.({block:'center',behavior:reduced?'auto':'smooth'});target.focus({preventScroll:true});highlightTimer=win.setTimeout(clearHighlight,1600);}
 function cancelPress(){if(timer!==null)win.clearTimeout(timer);timer=null;press=null;}
 function close({restore=true}={}){cancelPress();clearHighlight();selected=null;mode='message';if(dialog.open)dialog.close();dialog.replaceChildren();doc.body.classList.remove('staff-message-menu-open');if(restore&&trigger?.isConnected)trigger.focus({preventScroll:true});trigger=null;}
 function show(id,source){if(!live())return;const message=getMessage(id);if(!message)return;cancelPress();if(dialog.open)close();selected=message;trigger=source||root.querySelector('[data-message="'+id+'"] [data-message-actions]');
  dialog.innerHTML='<div class="staff-message-selection" dir="auto"><strong>'+esc(message.author_name)+'</strong><p>'+(message.redacted?uiLeaf('staffUi.helperMessageRemoved'):esc(String(message.body||message.preview||'').slice(0,800)))+'</p></div><div class="staff-message-menu-buttons">'+(!message.redacted&&canReply(message)?'<button type="button" data-message-menu="reply">'+uiLeaf('messageDeletionUi.reply')+'</button>':'')+(!message.redacted&&message.body?'<button type="button" data-message-menu="copy">'+uiLeaf('messageDeletionUi.copy')+'</button>':'')+'<button type="button" data-message-menu="self">'+uiLeaf('messageDeletionUi.self')+'</button>'+(message.author_id===actorId&&!message.redacted?'<button type="button" data-message-menu="everyone">'+uiLeaf('messageDeletionUi.everyone')+'</button>':'')+'</div>';
  dialog.setAttribute('aria-label',t('messageDeletionUi.actions'));dialog.showModal();doc.body.classList.add('staff-message-menu-open');dialog.querySelector('button')?.focus({preventScroll:true});
 }
 function openConversation(source){if(!live())return;const room=getRoom();if(!room)return;if(dialog.open)close();cancelPress();mode='room';selected={id:room.id};trigger=source;dialog.innerHTML='<div class="staff-message-selection"><strong dir="auto">'+esc(room.title)+'</strong></div><div class="staff-message-menu-buttons">'+(onTheme?'<button type="button" data-message-menu="theme">'+uiLeaf('conversationThemeUi.title')+'</button>':'')+'<button type="button" data-message-menu="clear-self">'+uiLeaf('messageDeletionUi.clearSelf')+'</button>'+(room.canClearEveryone===true?'<button type="button" data-message-menu="clear-everyone">'+uiLeaf('messageDeletionUi.clearEveryone')+'</button>':'')+'</div>';dialog.setAttribute('aria-label',t('messageDeletionUi.chatActions'));dialog.showModal();doc.body.classList.add('staff-message-menu-open');dialog.querySelector('button')?.focus({preventScroll:true});}
 const click=e=>{const quote=e.target.closest('button[data-reply-source]');if(quote&&root.contains(quote)){e.preventDefault();jumpToSource(quote.dataset.replySource);return;}const button=e.target.closest('[data-message-actions]');if(button&&root.contains(button)){e.preventDefault();show(button.closest('[data-message]').dataset.message,button);}};
 const down=e=>{if(e.pointerType!=='touch'||e.button&&e.button!==0||e.target.closest('button,a,input,textarea')||doc.getSelection?.()?.toString())return;const bubble=e.target.closest('[data-message]');if(!bubble||!root.contains(bubble))return;cancelPress();press={x:e.clientX,y:e.clientY,id:bubble.dataset.message,pointer:e.pointerId};timer=win.setTimeout(()=>{const pending=press;cancelPress();if(pending&&live()&&!doc.getSelection?.()?.toString())show(pending.id,bubble.querySelector('[data-message-actions]'));},500);};
 const move=e=>{if(press&&(e.pointerId!==press.pointer||Math.hypot(e.clientX-press.x,e.clientY-press.y)>8))cancelPress();};
 const context=e=>{if(dialog.open&&e.target.closest('[data-message]'))e.preventDefault();};
 const navigation=()=>close({restore:false}),hidden=()=>{if(doc.hidden)navigation();};
 dialog.addEventListener('cancel',e=>{e.preventDefault();e.stopPropagation();close();});
 dialog.addEventListener('click',e=>{if(e.target===dialog){close();return;}const button=e.target.closest('[data-message-menu]');if(!button||!selected||!live())return;if(mode==='room'){if(button.dataset.messageMenu==='theme'){const source=trigger;close();onTheme?.(source);return;}const room=getRoom(),scope=button.dataset.messageMenu==='clear-everyone'?'everyone':button.dataset.messageMenu==='clear-self'?'self':null;if(!room||room.id!==selected.id||!scope){close();return;}close();if(scope==='self'||room.canClearEveryone===true)onClear(room,scope);return;}const message=getMessage(selected.id),action=button.dataset.messageMenu;if(!message){close();return;}close();if(action==='reply'){if(!message.redacted&&canReply(message))onReply(message);return;}if(action==='self'||action==='everyone'){if(action==='self'||message.author_id===actorId&&!message.redacted)onDelete(message,action);return;}if(action==='copy'&&!message.redacted&&message.body){void(async()=>{try{if(win.navigator.clipboard?.writeText)await win.navigator.clipboard.writeText(message.body);else{const copyFocus=doc.activeElement,input=doc.createElement('textarea');input.value=message.body;input.className='staff-copy-buffer';root.append(input);try{input.select();if(!doc.execCommand?.('copy'))throw Error('copy_denied');}finally{input.remove();if(copyFocus?.isConnected)copyFocus.focus({preventScroll:true});}}if(live())onNotice('messageDeletionUi.copied');}catch{if(live())onNotice('messageDeletionUi.copyFailed',true);}})();}});
 dialog.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();return;}if(e.key==='Tab'){const buttons=[...dialog.querySelectorAll('button:not([disabled])')];if(!buttons.length)return;if(e.shiftKey&&doc.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&doc.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}}});
 root.addEventListener('click',click);root.addEventListener('pointerdown',down);root.addEventListener('pointermove',move);root.addEventListener('pointerup',cancelPress);root.addEventListener('pointercancel',cancelPress);root.addEventListener('contextmenu',context);root.addEventListener('scroll',cancelPress,true);doc.addEventListener('visibilitychange',hidden);win.addEventListener('pagehide',navigation);win.addEventListener('popstate',navigation);win.addEventListener('hashchange',navigation);
 const off=subscribeLanguage(()=>{if(live()){dialog.setAttribute('aria-label',t(mode==='room'?'messageDeletionUi.chatActions':'messageDeletionUi.actions'));translateUi(dialog);}});
 return{close,openConversation,jumpToSource,dispose(){if(disposed)return;close();disposed=true;off();root.removeEventListener('click',click);root.removeEventListener('pointerdown',down);root.removeEventListener('pointermove',move);root.removeEventListener('pointerup',cancelPress);root.removeEventListener('pointercancel',cancelPress);root.removeEventListener('contextmenu',context);root.removeEventListener('scroll',cancelPress,true);doc.removeEventListener('visibilitychange',hidden);win.removeEventListener('pagehide',navigation);win.removeEventListener('popstate',navigation);win.removeEventListener('hashchange',navigation);dialog.remove();}};
}
